85		for _, harness := range matrix.Harnesses {
86			t.Run(harness.Name, func(t *testing.T) {
87				for _, cap := range harness.Capabilities {
88					if cap.Status != "supported" {
89						continue
90					}
91	
92					if len(cap.Evidence) == 0 {
93						t.Errorf("capability %q declared supported but has no evidence", cap.Name)
94						continue
95					}
96	
97					for _, ev := range cap.Evidence {
98						switch ev.Type {
