255	func validateTestEvidenceExists(t *testing.T, harnessDir, harnessName, testID string) {
256		t.Helper()
257	
258		parts := strings.Split(testID, "::")
259		if len(parts) != 2 {
260			t.Errorf("invalid test evidence ID format %q (expected 'package::TestName')", testID)
261			return
262		}
263	
264		packagePath := parts[0]
265		testName := parts[1]
266	
267		lastSlash := strings.LastIndex(packagePath, "/")
268		if lastSlash < 0 {
269			t.Errorf("invalid test evidence package path %q", packagePath)
270			return
271		}
272	
273		pkgName := packagePath[lastSlash+1:]
274		pkgDir := filepath.Join(harnessDir, pkgName)
275	
276		if _, err := os.Stat(pkgDir); err != nil {
277			t.Logf("warning: harness package directory not found: %s", pkgDir)
278			return
279		}
280	
281		fset := token.NewFileSet()
282		pkgs, err := parser.ParseDir(fset, pkgDir, func(info fs.FileInfo) bool {
283			return strings.HasSuffix(info.Name(), "_test.go")
284		}, 0)
285	
286		if err != nil {
287			t.Logf("warning: could not parse %s for test validation: %v", pkgDir, err)
288			return
289		}
290	
291		found := false
292		for _, pkg := range pkgs {
293			for _, f := range pkg.Files {
294				for _, decl := range f.Decls {
295					if fn, ok := decl.(*ast.FuncDecl); ok {
296						if fn.Name.Name == testName {
297							found = true
298							break
299						}
300					}
301				}
302			}
303		}
304	
305		if !found {
306			t.Errorf("test %s not found in %s", testName, pkgDir)
307		}
308	}
