22	// TestClaudeTuiInterfaceConformance asserts (*claudetui.Harness)(nil)
23	// satisfies harnesses.Harness, harnesses.QuotaHarness,
24	// harnesses.AccountHarness, and harnesses.ModelDiscoveryHarness via
25	// compile-time var _ assertions per CONTRACT-004.
26	func TestClaudeTuiInterfaceConformance(t *testing.T) {
27		// The var _ assignments in harness.go compile-time-check interface
28		// satisfaction. This test verifies they are present and correct.
29		h := &claudetui.Harness{}
30	
31		// Verify runtime methods work.
32		if h.Info().Name != "claude-tui" {
33			t.Errorf("Info().Name: got %q, want \"claude-tui\"", h.Info().Name)
34		}
35	
36		// Verify all interface methods are callable.
37		_ = h.Info()
38		if err := h.HealthCheck(context.Background()); err != claudetui.ErrNotYetImplemented {
39			t.Errorf("HealthCheck returned %v, want ErrNotYetImplemented", err)
40		}
41		if _, err := h.Execute(context.Background(), harnesses.ExecuteRequest{}); err != claudetui.ErrNotYetImplemented {
42			t.Errorf("Execute returned %v, want ErrNotYetImplemented", err)
43		}
44		if _, err := h.QuotaStatus(context.Background(), time.Now()); err != claudetui.ErrNotYetImplemented {
45			t.Errorf("QuotaStatus returned %v, want ErrNotYetImplemented", err)
46		}
47		if _, err := h.RefreshQuota(context.Background()); err != claudetui.ErrNotYetImplemented {
48			t.Errorf("RefreshQuota returned %v, want ErrNotYetImplemented", err)
49		}
50		_ = h.QuotaFreshness()
51		_ = h.SupportedLimitIDs()
52		if _, err := h.AccountStatus(context.Background(), time.Now()); err != claudetui.ErrNotYetImplemented {
53			t.Errorf("AccountStatus returned %v, want ErrNotYetImplemented", err)
54		}
55		if _, err := h.RefreshAccount(context.Background()); err != claudetui.ErrNotYetImplemented {
56			t.Errorf("RefreshAccount returned %v, want ErrNotYetImplemented", err)
57		}
