package harnesses_test

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// TestPrimaryHarnessCapabilityBaselineHasClaudeTuiRow asserts the markdown file
// contains a claude-tui row with at least one entry per ADR-002 row schema.
func TestPrimaryHarnessCapabilityBaselineHasClaudeTuiRow(t *testing.T) {
	repoRoot := findRepoRoot(t)
	baselinePath := filepath.Join(repoRoot, "docs", "helix", "02-design", "primary-harness-capability-baseline.md")

	data, err := os.ReadFile(baselinePath)
	if err != nil {
		t.Fatalf("failed to read capability baseline: %v", err)
	}

	content := string(data)
	if !strings.Contains(content, "| claude-tui |") {
		t.Fatal("capability baseline missing claude-tui row")
	}

	expectedCapabilities := []string{"Run", "FinalText", "ProgressEvents", "Cancel", "WorkdirContext",
		"PermissionModes", "ListModels", "SetModel", "ListReasoning", "SetReasoning",
		"TokenUsage", "QuotaStatus", "ErrorStatus", "RequestMetadata"}

	for _, cap := range expectedCapabilities {
		if !strings.Contains(content, cap) {
			t.Errorf("capability baseline missing required column: %s", cap)
		}
	}
}

// TestClaudeTuiBillingObservationEvidenceCassette asserts the recorded billing-observation
// cassette is loadable, parses to a subscription-mode billing signal, and is referenced
// from ADR-013 frontmatter by its evidence ID.
func TestClaudeTuiBillingObservationEvidenceCassette(t *testing.T) {
	repoRoot := findRepoRoot(t)
	cassettePath := filepath.Join(repoRoot, "internal", "harnesses", "claude-tui", "testdata", "billing_observation", "manifest.json")

	data, err := os.ReadFile(cassettePath)
	if err != nil {
		t.Fatalf("failed to read billing observation cassette manifest: %v", err)
	}

	var manifest map[string]interface{}
	if err := json.Unmarshal(data, &manifest); err != nil {
		t.Fatalf("failed to unmarshal cassette manifest: %v", err)
	}

	evidenceID, ok := manifest["id"]
	if !ok {
		t.Fatal("cassette manifest missing 'id' field")
	}

	if evidenceID == "" {
		t.Fatal("cassette manifest 'id' is empty")
	}

	billingObs, ok := manifest["billing_observation"].(map[string]interface{})
	if !ok {
		t.Fatal("cassette manifest missing 'billing_observation' field")
	}

	before, ok := billingObs["usage_window_before"]
	if !ok {
		t.Fatal("billing_observation missing 'usage_window_before'")
	}
	if before == nil {
		t.Fatal("usage_window_before is nil")
	}

	after, ok := billingObs["usage_window_after"]
	if !ok {
		t.Fatal("billing_observation missing 'usage_window_after'")
	}
	if after == nil {
		t.Fatal("usage_window_after is nil")
	}

	adrPath := filepath.Join(repoRoot, "docs", "helix", "02-design", "adr", "ADR-013-claude-tui-pty-harness-fork.md")
	adrData, err := os.ReadFile(adrPath)
	if err != nil {
		t.Fatalf("failed to read ADR-013: %v", err)
	}

	adrContent := string(adrData)
	if !strings.Contains(adrContent, evidenceID.(string)) {
		t.Errorf("ADR-013 does not reference billing observation evidence ID: %v", evidenceID)
	}
}

// TestCapabilityMatrixEvidenceIDRequired asserts the matrix CI gate fails when
// any claude-tui row marked supported has an empty evidence_id, and passes when
// all supported rows cite a present cassette.
func TestCapabilityMatrixEvidenceIDRequired(t *testing.T) {
	matrix := loadCapabilityMatrix(t)

	var claudeTui *Harness
	for i, h := range matrix.Harnesses {
		if h.Name == "claude-tui" {
			claudeTui = &matrix.Harnesses[i]
			break
		}
	}

	if claudeTui == nil {
		t.Fatal("claude-tui not found in capability matrix")
	}

	for _, cap := range claudeTui.Capabilities {
		if cap.Status != "supported" {
			continue
		}

		for _, ev := range cap.Evidence {
			if ev.Type != "cassette" {
				continue
			}

			if ev.EvidenceID == "" {
				t.Errorf("claude-tui.%s has cassette evidence without evidence_id field", cap.Name)
			}
		}
	}
}

// TestClaudeTuiRowsPromotedOnlyWithEvidence asserts every row currently marked
// supported for claude-tui resolves to a present cassette file on disk.
func TestClaudeTuiRowsPromotedOnlyWithEvidence(t *testing.T) {
	matrix := loadCapabilityMatrix(t)
	harnessDir := currentHarnessDir(t)

	var claudeTui *Harness
	for i, h := range matrix.Harnesses {
		if h.Name == "claude-tui" {
			claudeTui = &matrix.Harnesses[i]
			break
		}
	}

	if claudeTui == nil {
		t.Fatal("claude-tui not found in capability matrix")
	}

	for _, cap := range claudeTui.Capabilities {
		if cap.Status != "supported" {
			continue
		}

		for _, ev := range cap.Evidence {
			if ev.Type != "cassette" {
				continue
			}

			cassettePath := filepath.Join(harnessDir, ev.ID, "manifest.json")
			if _, err := os.Stat(cassettePath); err != nil {
				t.Errorf("cassette for claude-tui.%s not found at %s: %v", cap.Name, cassettePath, err)
			}
		}
	}
}

// TestADR013StatusAccepted asserts the ADR-013 frontmatter status field equals
// "accepted" and references the billing-observation evidence ID.
func TestADR013StatusAccepted(t *testing.T) {
	repoRoot := findRepoRoot(t)
	adrPath := filepath.Join(repoRoot, "docs", "helix", "02-design", "adr", "ADR-013-claude-tui-pty-harness-fork.md")

	data, err := os.ReadFile(adrPath)
	if err != nil {
		t.Fatalf("failed to read ADR-013: %v", err)
	}

	content := string(data)

	// Extract frontmatter status
	if !strings.Contains(content, "status: accepted") {
		t.Error("ADR-013 status is not 'accepted'")
	}

	// Verify billing observation evidence ID is referenced
	if !strings.Contains(content, "claude-tui-billing-observation") {
		t.Error("ADR-013 does not reference billing observation evidence ID")
	}
}

// findRepoRoot finds the git repository root by walking up directories.
func findRepoRoot(t *testing.T) string {
	t.Helper()
	cwd, err := os.Getwd()
	if err != nil {
		t.Fatalf("failed to get working directory: %v", err)
	}

	for {
		if _, err := os.Stat(filepath.Join(cwd, ".git")); err == nil {
			return cwd
		}
		parent := filepath.Dir(cwd)
		if parent == cwd {
			t.Fatal("could not find git repository root")
		}
		cwd = parent
	}
}
